library(SparkR, lib.loc = file.path(Sys.getenv("SPARK_HOME"), "R", "lib"))
sparkR.session()
args <- commandArgs(trailingOnly = TRUE)
stopifnot(length(args) == 2L)
rows <- count(createDataFrame(data.frame(id = 1:3)))
stopifnot(rows == 3)
result <- createDataFrame(data.frame(value = paste0(args[[2L]], ":", rows)))
write.df(result, args[[1L]], source = "text", mode = "error")
sparkR.session.stop()
